CREATE TABLE patients (id BIGINT PRIMARY KEY AUTO_INCREMENT, code VARCHAR(40) NOT NULL UNIQUE, display_name VARCHAR(100) NOT NULL, date_of_birth DATE);
CREATE TABLE wards (id BIGINT PRIMARY KEY AUTO_INCREMENT, name VARCHAR(80) NOT NULL UNIQUE);
CREATE TABLE beds (id BIGINT PRIMARY KEY AUTO_INCREMENT, ward_id BIGINT NOT NULL, label VARCHAR(40) NOT NULL, UNIQUE(ward_id,label), FOREIGN KEY(ward_id) REFERENCES wards(id));
CREATE TABLE admissions (id BIGINT PRIMARY KEY AUTO_INCREMENT, patient_id BIGINT NOT NULL, bed_id BIGINT NOT NULL, status VARCHAR(20) NOT NULL, admitted_at TIMESTAMP(6) NOT NULL, discharged_at TIMESTAMP(6), active_bed BIGINT GENERATED ALWAYS AS (CASE WHEN status='ACTIVE' THEN bed_id ELSE NULL END) STORED UNIQUE, active_patient BIGINT GENERATED ALWAYS AS (CASE WHEN status='ACTIVE' THEN patient_id ELSE NULL END) STORED UNIQUE, FOREIGN KEY(patient_id) REFERENCES patients(id), FOREIGN KEY(bed_id) REFERENCES beds(id), INDEX idx_admission_patient(patient_id,admitted_at));
CREATE TABLE devices (id BIGINT PRIMARY KEY AUTO_INCREMENT, serial VARCHAR(80) NOT NULL UNIQUE, adapter_type VARCHAR(30) NOT NULL, online BOOLEAN NOT NULL DEFAULT FALSE);
CREATE TABLE device_assignments (id BIGINT PRIMARY KEY AUTO_INCREMENT, device_id BIGINT NOT NULL, admission_id BIGINT NOT NULL, assigned_at TIMESTAMP(6) NOT NULL, ended_at TIMESTAMP(6), active_device BIGINT GENERATED ALWAYS AS (CASE WHEN ended_at IS NULL THEN device_id ELSE NULL END) STORED UNIQUE, FOREIGN KEY(device_id) REFERENCES devices(id), FOREIGN KEY(admission_id) REFERENCES admissions(id));
CREATE TABLE data_sources (id BIGINT PRIMARY KEY AUTO_INCREMENT, name VARCHAR(100) NOT NULL, type VARCHAR(20) NOT NULL, provenance VARCHAR(500) NOT NULL);
CREATE TABLE source_recordings (id BIGINT PRIMARY KEY AUTO_INCREMENT, source_id BIGINT NOT NULL, name VARCHAR(100) NOT NULL, start_at TIMESTAMP(6) NOT NULL, end_at TIMESTAMP(6) NOT NULL, FOREIGN KEY(source_id) REFERENCES data_sources(id), CHECK(end_at>start_at));
CREATE TABLE measurements (id BIGINT PRIMARY KEY AUTO_INCREMENT, event_id VARCHAR(100) NOT NULL, admission_id BIGINT NOT NULL, device_id BIGINT NOT NULL, metric VARCHAR(20) NOT NULL, value DOUBLE NULL, unit VARCHAR(30) NOT NULL, observed_at TIMESTAMP(6) NOT NULL, received_at TIMESTAMP(6) NOT NULL, source_id BIGINT NOT NULL, recording_id BIGINT NULL, quality VARCHAR(20) NOT NULL, UNIQUE(source_id,event_id), FOREIGN KEY(admission_id) REFERENCES admissions(id), FOREIGN KEY(device_id) REFERENCES devices(id), FOREIGN KEY(source_id) REFERENCES data_sources(id), FOREIGN KEY(recording_id) REFERENCES source_recordings(id), INDEX idx_measurement_history(admission_id,metric,observed_at,id), CHECK((quality IN ('MISSING','INVALID') AND value IS NULL) OR (quality NOT IN ('MISSING','INVALID') AND value IS NOT NULL)));
CREATE TABLE waveform_chunks (id BIGINT PRIMARY KEY AUTO_INCREMENT, event_id VARCHAR(100) NOT NULL, admission_id BIGINT NOT NULL, device_id BIGINT NOT NULL, metric VARCHAR(20) NOT NULL, unit VARCHAR(30) NOT NULL, observed_at TIMESTAMP(6) NOT NULL, received_at TIMESTAMP(6) NOT NULL, sample_rate_hz DOUBLE NOT NULL, samples JSON NOT NULL, source_id BIGINT NOT NULL, recording_id BIGINT NULL, quality VARCHAR(20) NOT NULL, UNIQUE(source_id,event_id), FOREIGN KEY(admission_id) REFERENCES admissions(id), FOREIGN KEY(device_id) REFERENCES devices(id), FOREIGN KEY(source_id) REFERENCES data_sources(id), FOREIGN KEY(recording_id) REFERENCES source_recordings(id), INDEX idx_waveform_history(admission_id,metric,observed_at,id));
CREATE TABLE alert_rules (id BIGINT PRIMARY KEY AUTO_INCREMENT, admission_id BIGINT NOT NULL, metric VARCHAR(20) NOT NULL, lower_bound DOUBLE, upper_bound DOUBLE, persistence_seconds INT NOT NULL, max_gap_seconds INT NOT NULL, severity VARCHAR(20) NOT NULL, enabled BOOLEAN NOT NULL DEFAULT TRUE, FOREIGN KEY(admission_id) REFERENCES admissions(id), CHECK(lower_bound IS NOT NULL OR upper_bound IS NOT NULL));
CREATE TABLE alerts (id BIGINT PRIMARY KEY AUTO_INCREMENT, admission_id BIGINT NOT NULL, rule_id BIGINT NOT NULL, metric VARCHAR(20) NOT NULL, severity VARCHAR(20) NOT NULL, state VARCHAR(20) NOT NULL, started_at TIMESTAMP(6) NOT NULL, triggered_at TIMESTAMP(6) NOT NULL, value DOUBLE, unit VARCHAR(30) NOT NULL, quality VARCHAR(20) NOT NULL, source_id BIGINT NOT NULL, version BIGINT NOT NULL DEFAULT 0, active_rule BIGINT GENERATED ALWAYS AS (CASE WHEN state!='RESOLVED' THEN rule_id ELSE NULL END) STORED UNIQUE, FOREIGN KEY(admission_id) REFERENCES admissions(id), FOREIGN KEY(rule_id) REFERENCES alert_rules(id), FOREIGN KEY(source_id) REFERENCES data_sources(id), INDEX idx_alert_history(admission_id,triggered_at,id));
CREATE TABLE alert_events (id BIGINT PRIMARY KEY AUTO_INCREMENT, alert_id BIGINT NOT NULL, actor VARCHAR(100) NOT NULL, action VARCHAR(40) NOT NULL, occurred_at TIMESTAMP(6) NOT NULL, FOREIGN KEY(alert_id) REFERENCES alerts(id));
CREATE TABLE simulation_sessions (id BIGINT PRIMARY KEY AUTO_INCREMENT, admission_id BIGINT NOT NULL, recording_id BIGINT NOT NULL, output_recording_id BIGINT NOT NULL, state VARCHAR(20) NOT NULL, speed DOUBLE NOT NULL, cursor_at TIMESTAMP(6) NOT NULL, updated_at TIMESTAMP(6) NOT NULL, FOREIGN KEY(admission_id) REFERENCES admissions(id), FOREIGN KEY(recording_id) REFERENCES source_recordings(id));
CREATE TABLE simulation_events (session_id BIGINT NOT NULL, original_event VARCHAR(120) NOT NULL, PRIMARY KEY(session_id,original_event), FOREIGN KEY(session_id) REFERENCES simulation_sessions(id));
CREATE TABLE clinical_contexts (admission_id BIGINT PRIMARY KEY, supplemental_oxygen BOOLEAN, spo2_scale INT, consciousness VARCHAR(40), notes TEXT, FOREIGN KEY(admission_id) REFERENCES admissions(id));
CREATE TABLE analytics_snapshots (id BIGINT PRIMARY KEY AUTO_INCREMENT, admission_id BIGINT NOT NULL, computed_at TIMESTAMP(6) NOT NULL, payload JSON NOT NULL, FOREIGN KEY(admission_id) REFERENCES admissions(id));
CREATE TABLE reports (id BIGINT PRIMARY KEY AUTO_INCREMENT, admission_id BIGINT, ward_id BIGINT, from_at TIMESTAMP(6) NOT NULL, to_at TIMESTAMP(6) NOT NULL, created_at TIMESTAMP(6) NOT NULL, created_by VARCHAR(100) NOT NULL, content LONGTEXT NOT NULL, FOREIGN KEY(admission_id) REFERENCES admissions(id), FOREIGN KEY(ward_id) REFERENCES wards(id), CHECK((admission_id IS NULL) <> (ward_id IS NULL)));
CREATE TABLE users (id BIGINT PRIMARY KEY AUTO_INCREMENT, username VARCHAR(100) NOT NULL UNIQUE, password_hash VARCHAR(100) NOT NULL, role VARCHAR(20) NOT NULL, enabled BOOLEAN NOT NULL DEFAULT TRUE);
CREATE TABLE user_wards (user_id BIGINT NOT NULL, ward_id BIGINT NOT NULL, PRIMARY KEY(user_id,ward_id), FOREIGN KEY(user_id) REFERENCES users(id), FOREIGN KEY(ward_id) REFERENCES wards(id));
CREATE TABLE audit_events (id BIGINT PRIMARY KEY AUTO_INCREMENT, actor VARCHAR(100) NOT NULL, action VARCHAR(100) NOT NULL, resource VARCHAR(200) NOT NULL, occurred_at TIMESTAMP(6) NOT NULL, INDEX idx_audit_time(occurred_at,id));
